    static func style(size: Size, requiredPlacement: RequiredPlacement, titlePlacement: TitlePlacement, view: View) -> AppearanceVariation<FormItemAppearance> {
        resolve(size: size, requiredPlacement: requiredPlacement, titlePlacement: titlePlacement, view: view).style
    }

    /// Список настраиваемых «ручек» компонента для binding-конфигуратора.
    static let bindingProperties: [BindingProperty] = [
        BindingProperty(name: "size", kind: .singleChoice(["xs", "s", "m", "l"]), defaultValue: "xs"),
        BindingProperty(name: "required-placement", kind: .singleChoice(["none", "start", "end"]), defaultValue: "none"),
        BindingProperty(name: "title-placement", kind: .singleChoice(["none", "top", "start"]), defaultValue: "none"),
        BindingProperty(name: "view", kind: .singleChoice(["default", "positive", "negative", "warning"]), defaultValue: "default"),
    ]

    /// Резолвит стиль по значениям binding-«ручек» (raw-строки).
    /// Неизвестные/пустые значения размерности берут дефолт.
    static func resolveStyle(bindings: [String: String]) -> AppearanceVariation<FormItemAppearance> {
        let size = Size(raw: bindings["size"] ?? "") ?? .xs
        let requiredPlacement = RequiredPlacement(raw: bindings["required-placement"] ?? "") ?? .none
        let titlePlacement = TitlePlacement(raw: bindings["title-placement"] ?? "") ?? .none
        let view = View(raw: bindings["view"] ?? "") ?? .`default`
        return style(size: size, requiredPlacement: requiredPlacement, titlePlacement: titlePlacement, view: view)
    }
